<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import MetricChart from '../components/insights/MetricChart.vue'
import {loadInsights,type Metric} from '../services/insights'
const tabs=[{id:'catalog/summary',name:'电影库分析'},{id:'me/behavior',name:'个人行为洞察'},{id:'me/ai-usage',name:'AI用量'},{id:'recommendation/evaluation',name:'推荐评估'}]
const connection=ref('未读取'),tab=ref(tabs[0]!.id),from=ref(''),to=ref(''),busy=ref(false),error=ref(''),metrics=ref<Metric[]>([]);let controller:AbortController|undefined,serial=0
async function load(){const id=++serial;controller?.abort();controller=new AbortController();busy.value=true;error.value='';metrics.value=[];try{const data=await loadInsights(tab.value,from.value,to.value,controller.signal);if(id===serial){metrics.value=data;if(tab.value==='me/ai-usage'){try{const r=await fetch('/api/v1/assistant/status');const s=await r.json();connection.value=r.ok?(s.data.configured?s.data.model+' · '+(s.data.enabled?'已启用':'未启用'):'未连接个人模型'):'模型连接状态不可得'}catch{connection.value='模型连接状态不可得'}}}}catch(e){if(id===serial&&(e as Error).name!=='AbortError')error.value=(e as Error).message}finally{if(id===serial)busy.value=false}}
function choose(id:string){tab.value=id;load()}
const names:Record<string,string>={'active_movie_count':'活跃电影数','status_distribution':'目录状态','source_coverage':'外部来源覆盖','rating_coverage':'评分来源覆盖','genres_distribution':'影片类型','decades_distribution':'上映年代','overview_completeness':'有效简介覆盖率','poster_coverage':'可访问海报覆盖率','ingest_batches':'导入批次状态','ingest_items':'导入条目状态','data_quality_issues':'质量问题状态','rating':'已评分影片','favorite':'收藏影片','want':'想看影片','watched':'已看影片','not_interested':'不感兴趣影片','daily_events':'每日行为事件','genre_preferences':'正反馈类型偏好','usage':'个人模型用量','bill_amount':'真实账单','latency':'请求耗时','precision_at_10':'Precision@10','recall_at_10':'Recall@10','ndcg_at_10':'NDCG@10','coverage_at_10':'Item Coverage@10'}
const label=(m:Metric)=>names[m.metric_id.split('.').pop()!]||m.metric_id
const states:Record<string,string>={OK:'可用',NO_DATA:'暂无数据',INSUFFICIENT_DATA:'样本不足',UNKNOWN:'未知',UNAVAILABLE:'不可得'}
function rows(m:Metric){if(Array.isArray(m.value))return m.value.map((x:any)=>({label:x.date,value:x.count}));if(m.value&&typeof m.value==='object')return Object.entries(m.value).filter(([,v])=>typeof v==='number').map(([k,v])=>({label:k,value:v as number}));return []}
function display(m:Metric){return m.value===null?'N/A':m.unit==='ratio'?(m.value*100).toFixed(1)+'%':String(m.value)}
const usage=computed(()=>metrics.value.find(m=>m.metric_id==='ai.usage')?.value)
onMounted(load);onBeforeUnmount(()=>controller?.abort())
</script>
<template><main class="insights"><header><h1>数据洞察</h1><nav><router-link to="/home">账户</router-link><router-link to="/movies">电影与助手</router-link></nav></header><p>电影库与本人数据 · 数据不足或费用未知时如实展示。时间趋势按UTC统计，区间为开始含、结束不含；当前状态与电影库为全量快照。</p><div class="tabs" role="tablist" aria-label="分析模块"><button v-for="t in tabs" :key="t.id" role="tab" :aria-selected="tab===t.id" @click="choose(t.id)">{{t.name}}</button></div><form @submit.prevent="load"><label>开始日期（UTC）<input type="date" v-model="from"></label><label>结束日期（UTC，不含）<input type="date" v-model="to"></label><button :disabled="busy">刷新数据</button></form><p v-if="busy" role="status">正在读取真实数据…</p><div v-else-if="error" role="alert">{{error}} <button @click="load">重试</button></div><template v-else><p v-if="tab==='catalog/summary'" class="notice">当前已验真活跃影片：{{metrics[0]?.value??'未知'}}部。小样本分布参考意义有限，不代表外部平台全量电影。</p><p v-if="tab==='recommendation/evaluation'" class="notice">暂无足够且完成独立时间留出的真实交互。下列N/A不代表算法得分为零；合成测试仅验证计算器，不能证明推荐改进。</p><div class="cards"><article v-for="m in metrics" :key="m.metric_id"><h2>{{label(m)}}</h2><p class="state">{{states[m.status]||m.status}} · 样本 {{m.sample_size}}</p><template v-if="m.metric_id==='ai.usage'&&usage"><p>当前连接：{{connection}}</p><p>请求状态（保留创建时间的账本）：{{usage.request_states}}</p><p>实际派发 {{usage.calls}} 次 · 用量未知 {{usage.unknown_calls}} 次</p><p>已知输入 {{usage.known_tokens.input_tokens??'未知'}} / 输出 {{usage.known_tokens.output_tokens??'未知'}} / 缓存输入 {{usage.known_tokens.cached_input_tokens??'未知'}}</p><p>缓存输入包含在输入中，不重复累加。真实账单未知，Token不等于收费账单。</p><MetricChart title="每日模型调用" :rows="usage.daily_models.map((x:any)=>({label:x.date+' '+x.model+' '+x.provenance,value:x.calls}))"/><MetricChart title="Token组成（已知部分；缓存为输入子集）" :rows="usage.daily_models.map((x:any)=>({label:x.date+' '+x.model,value:x.input_tokens}))" :stacks="[{name:'非缓存输入',values:usage.daily_models.map((x:any)=>x.uncached_input_tokens)},{name:'缓存输入',values:usage.daily_models.map((x:any)=>x.cached_input_tokens)},{name:'输出',values:usage.daily_models.map((x:any)=>x.output_tokens)}]"/><table><caption>模型与来源分组；历史Mock不作为真实服务商用量</caption><thead><tr><th>日期/模型/来源</th><th>输入</th><th>输出</th><th>缓存输入（子集）</th><th>未知次数</th></tr></thead><tbody><tr v-for="(x,i) in usage.daily_models" :key="i"><td>{{x.date}} {{x.model}} {{x.provenance}} {{x.paid_request?'计费派发标记（非实扣）':'非计费标记'}}</td><td>{{x.input_tokens??'未知'}}</td><td>{{x.output_tokens??'未知'}}</td><td>{{x.cached_input_tokens??'未知'}}</td><td>{{x.unknown_calls}}</td></tr></tbody></table></template><MetricChart v-else-if="rows(m).length" :title="label(m)" :rows="rows(m)" :line="m.metric_id==='behavior.daily_events'"/><p v-else-if="m.value!==null&&typeof m.value==='object'">当前范围暂无数据。</p><strong v-else>{{display(m)}}</strong><details><summary>指标口径与来源</summary><p>{{m.notes}}</p><p>来源：{{m.source}} · 范围：{{m.scope}}</p><p>分母：{{m.denominator??'不适用'}} · 定义 {{m.definition_version}}</p><p>统计窗口：{{m.window.from??'全量快照'}} — {{m.window.to??'当前'}}</p><time :datetime="m.as_of">更新：{{new Date(m.as_of).toLocaleString()}}</time></details></article></div></template></main></template>
<style scoped>.insights{background:#f5f7fa;color:#182b39;min-height:100vh;padding:32px;position:relative;z-index:1;overflow-wrap:anywhere;font:16px/1.6 system-ui,sans-serif}header,nav,.tabs,form{display:flex;gap:16px;flex-wrap:wrap;align-items:center}header{justify-content:space-between}a{color:#165777}button,input{font:inherit;padding:8px 12px;border:1px solid #96aab7;background:white;color:#182b39;border-radius:4px}button{cursor:pointer}button[aria-selected=true]{background:#185d7b;color:white}button:disabled{opacity:.6}label{display:flex;flex-direction:column;font-size:14px}form{margin:24px 0;align-items:end}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}article{background:white;border:1px solid #d4dce1;padding:22px;min-width:0}h2{font-size:20px}strong{font-size:30px}.state,details{font-size:13px;color:#455b69}details{margin-top:20px}summary{cursor:pointer}.notice{background:#fff5d5;padding:16px}table{width:100%;border-collapse:collapse;font-size:12px}td,th{border-bottom:1px solid #d4dce1;text-align:left;padding:5px}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #ce8a19;outline-offset:3px}@media(max-width:700px){.insights{padding:18px}.cards{grid-template-columns:1fr}form label{width:100%}article{padding:16px}}</style>


